package dev.alien.client.studio;
import dev.alien.client.AlienClient;import dev.alien.client.scene.*;import dev.alien.client.hud.UltimateHud;
import net.minecraft.client.Minecraft;import net.minecraft.client.renderer.GlStateManager;import net.minecraft.entity.*;import net.minecraftforge.client.event.*;import net.minecraftforge.event.entity.living.LivingDeathEvent;import net.minecraftforge.fml.common.eventhandler.*;import net.minecraftforge.fml.common.gameevent.TickEvent;import org.lwjgl.opengl.GL11;import org.lwjgl.input.Keyboard;
import java.util.*;
/** Bounded local embellishments driven by actual entities/input, never packets. */
public final class StudioVisuals {
    private static long targetFrames,afterglowFrames,tagFrames,zoomFrames,handFrames;private static int glowCount;private final Deque<double[]> deaths=new ArrayDeque<double[]>();private Object world,profile;private int ticks;private final Set<Integer> customTags=new HashSet<Integer>();private final Map<Integer,Integer> dead=new HashMap<Integer,Integer>();
    public static long targetFrames(){return targetFrames;}public static long afterglowFrames(){return afterglowFrames;}public static long tagFrames(){return tagFrames;}public static long zoomFrames(){return zoomFrames;}public static long handFrames(){return handFrames;}public static int glowCount(){return glowCount;}
    @SubscribeEvent public void tick(TickEvent.ClientTickEvent e){if(e.phase!=TickEvent.Phase.END)return;Minecraft m=Minecraft.getMinecraft();if(world!=m.theWorld||profile!=AlienClient.get().config().scenes){world=m.theWorld;profile=AlienClient.get().config().scenes;deaths.clear();dead.clear();ticks=0;}if(!m.isGamePaused())ticks++;SceneConfig c=AlienClient.get().config().scenes;if(m.theWorld==null||!c.enabled||!c.afterglow){deaths.clear();dead.clear();}else{dead.entrySet().removeIf(p->ticks-p.getValue()>80);int examined=0;for(Object obj:m.theWorld.loadedEntityList){if(examined++>=256)break;if(obj instanceof EntityLivingBase){EntityLivingBase living=(EntityLivingBase)obj;if(living.deathTime>0||living.getHealth()<=0)remember(living,c,m);}}}while(!deaths.isEmpty()&&ticks-deaths.peekFirst()[3]>60)deaths.removeFirst();glowCount=deaths.size();}
    @SubscribeEvent public void death(LivingDeathEvent e){Minecraft m=Minecraft.getMinecraft();SceneConfig c=AlienClient.get().config().scenes;if(m.theWorld!=null&&e.entityLiving.worldObj==m.theWorld&&c.enabled&&c.afterglow&&m.thePlayer.getDistanceSqToEntity(e.entityLiving)<=c.distance*c.distance){remember(e.entityLiving,c,m);}}
    private void remember(EntityLivingBase living,SceneConfig c,Minecraft m){if(dead.containsKey(living.getEntityId())||dead.size()>=128||m.thePlayer==null||m.thePlayer.getDistanceSqToEntity(living)>c.distance*c.distance)return;dead.put(living.getEntityId(),ticks);if(deaths.size()==16)deaths.removeFirst();deaths.addLast(new double[]{living.posX,living.posY,living.posZ,ticks});}
    @SubscribeEvent public void fov(FOVUpdateEvent e){Minecraft m=Minecraft.getMinecraft();if(AlienClient.get().config().studio.zoom&&m.currentScreen==null&&Keyboard.isKeyDown(Keyboard.KEY_C)){e.newfov/=AlienClient.get().config().studio.zoomFactor;zoomFrames++;}}
    private java.lang.reflect.Method handFov,hurt,bob;
    @SubscribeEvent public void hand(RenderHandEvent e){Minecraft m=Minecraft.getMinecraft();StudioConfig c=AlienClient.get().config().studio;if(!c.handMovement||m.thePlayer==null||m.gameSettings.thirdPersonView!=0||m.currentScreen!=null||m.thePlayer.isPlayerSleeping()||m.playerController.isSpectator())return;
        if(handFov==null)try{handFov=net.minecraftforge.fml.relauncher.ReflectionHelper.findMethod(net.minecraft.client.renderer.EntityRenderer.class,m.entityRenderer,new String[]{"getFOVModifier","func_78481_a"},float.class,boolean.class);hurt=net.minecraftforge.fml.relauncher.ReflectionHelper.findMethod(net.minecraft.client.renderer.EntityRenderer.class,m.entityRenderer,new String[]{"hurtCameraEffect","func_78482_e"},float.class);bob=net.minecraftforge.fml.relauncher.ReflectionHelper.findMethod(net.minecraft.client.renderer.EntityRenderer.class,m.entityRenderer,new String[]{"setupViewBobbing","func_78475_f"},float.class);}catch(RuntimeException unavailable){handFov=hurt=bob=null;AlienClient.LOG.warn("Hand motion unavailable; preserving vanilla hand",unavailable);return;}
        int matrix=GL11.glGetInteger(GL11.GL_MATRIX_MODE);GL11.glMatrixMode(GL11.GL_PROJECTION);GL11.glPushMatrix();GL11.glMatrixMode(GL11.GL_MODELVIEW);GL11.glPushMatrix();
        try{float fov=(Float)handFov.invoke(m.entityRenderer,e.partialTicks,false);GL11.glMatrixMode(GL11.GL_PROJECTION);GL11.glLoadIdentity();if(m.gameSettings.anaglyph)GL11.glTranslatef(-(e.renderPass*2-1)*.07f,0,0);org.lwjgl.util.glu.GLU.gluPerspective(fov,m.displayWidth/(float)m.displayHeight,.05f,m.gameSettings.renderDistanceChunks*32);GL11.glMatrixMode(GL11.GL_MODELVIEW);GL11.glLoadIdentity();if(m.gameSettings.anaglyph)GL11.glTranslatef((e.renderPass*2-1)*.1f,0,0);
            GlStateManager.pushMatrix();try{hurt.invoke(m.entityRenderer,e.partialTicks);if(m.gameSettings.viewBobbing)bob.invoke(m.entityRenderer,e.partialTicks);double t=(m.thePlayer.ticksExisted+e.partialTicks)*.075;GlStateManager.translate(Math.sin(t)*.018*c.handStrength,Math.sin(t*.7)*.012*c.handStrength,0);GlStateManager.rotate((float)Math.sin(t)*1.8f*c.handStrength,0,0,1);if(!m.gameSettings.hideGUI){m.entityRenderer.enableLightmap();try{m.getItemRenderer().renderItemInFirstPerson(e.partialTicks);}finally{m.entityRenderer.disableLightmap();}}}finally{GlStateManager.popMatrix();}m.getItemRenderer().renderOverlays(e.partialTicks);e.setCanceled(true);handFrames++;
        }catch(ReflectiveOperationException failure){AlienClient.LOG.warn("Hand motion failed; preserving vanilla hand",failure);}finally{GL11.glMatrixMode(GL11.GL_MODELVIEW);GL11.glPopMatrix();GL11.glMatrixMode(GL11.GL_PROJECTION);GL11.glPopMatrix();GL11.glMatrixMode(matrix);}
    }
    @SubscribeEvent public void frame(TickEvent.RenderTickEvent e){if(e.phase==TickEvent.Phase.START)customTags.clear();}
    @SubscribeEvent public void atlas(TextureStitchEvent.Post e){MenuScene.invalidate();}
    @SubscribeEvent public void nativeTag(RenderLivingEvent.Specials.Pre e){Minecraft m=Minecraft.getMinecraft();if(AlienClient.get().config().studio.nameTags&&e.entity instanceof net.minecraft.entity.player.EntityPlayer&&m.thePlayer!=null&&e.entity!=m.thePlayer&&customTags.size()<Math.min(16,AlienClient.get().performance().cosmeticBudget())&&!e.entity.isInvisibleToPlayer(m.thePlayer)&&m.thePlayer.canEntityBeSeen(e.entity)&&m.thePlayer.getDistanceSqToEntity(e.entity)<=AlienClient.get().config().scenes.distance*AlienClient.get().config().scenes.distance){customTags.add(e.entity.getEntityId());e.setCanceled(true);}}
    @SubscribeEvent(priority=EventPriority.LOWEST) public void render(RenderWorldLastEvent e){Minecraft m=Minecraft.getMinecraft();if(m.thePlayer==null||m.theWorld==null)return;SceneConfig c=AlienClient.get().config().scenes;StudioConfig s=AlienClient.get().config().studio;if((!c.enabled||(!c.targetEsp&&!c.afterglow))&&!s.nameTags)return;
        Entity view=m.getRenderViewEntity();double x=view.lastTickPosX+(view.posX-view.lastTickPosX)*e.partialTicks,y=view.lastTickPosY+(view.posY-view.lastTickPosY)*e.partialTicks,z=view.lastTickPosZ+(view.posZ-view.lastTickPosZ)*e.partialTicks;GL11.glPushAttrib(GL11.GL_ALL_ATTRIB_BITS);GL11.glPushMatrix();
        try{GL11.glTranslated(-x,-y,-z);GL11.glDisable(GL11.GL_TEXTURE_2D);GL11.glDisable(GL11.GL_LIGHTING);GL11.glEnable(GL11.GL_BLEND);GL11.glBlendFunc(GL11.GL_SRC_ALPHA,GL11.GL_ONE);GL11.glDepthMask(false);GL11.glDisable(GL11.GL_ALPHA_TEST);
            if(c.enabled&&c.targetEsp){Entity target=m.theWorld.getEntityByID(UltimateHud.trackedEntity());if(target instanceof EntityLivingBase&&!target.isDead&&m.thePlayer.canEntityBeSeen(target)&&m.thePlayer.getDistanceSqToEntity(target)<c.distance*c.distance){double tx=target.lastTickPosX+(target.posX-target.lastTickPosX)*e.partialTicks,ty=target.lastTickPosY+(target.posY-target.lastTickPosY)*e.partialTicks+.06,tz=target.lastTickPosZ+(target.posZ-target.lastTickPosZ)*e.partialTicks;ring(tx,ty,tz,target.width*.8+.2,c.color,(ticks+e.partialTicks)*.05);targetFrames++;}}
            if(c.enabled&&c.afterglow&&!deaths.isEmpty()){GL11.glPointSize(4);GL11.glBegin(GL11.GL_POINTS);for(double[] p:deaths){double age=(ticks+e.partialTicks-p[3])/20;GL11.glColor4f((c.color>>16&255)/255f,(c.color>>8&255)/255f,(c.color&255)/255f,(float)Math.max(0,1-age/3));for(int i=0;i<48;i++){double a=i*2.4;GL11.glVertex3d(p[0]+Math.sin(a)*(.2+age*.4),p[1]+age*.5+(i%12)*.08,p[2]+Math.cos(a)*(.2+age*.4));}}GL11.glEnd();afterglowFrames++;}
        }finally{GL11.glPopMatrix();GL11.glPopAttrib();}
        if(s.nameTags){int n=0;for(Object o:m.theWorld.playerEntities){net.minecraft.entity.player.EntityPlayer p=(net.minecraft.entity.player.EntityPlayer)o;if(!customTags.contains(p.getEntityId())||p==m.thePlayer||p.isInvisibleToPlayer(m.thePlayer)||p.isDead||!m.thePlayer.canEntityBeSeen(p)||m.thePlayer.getDistanceSqToEntity(p)>c.distance*c.distance||n++>=Math.min(16,AlienClient.get().performance().cosmeticBudget()))continue;tag(p,x,y,z,e.partialTicks);}}
    }
    private static void ring(double x,double y,double z,double r,int rgb,double time){GL11.glLineWidth(2);for(int band=0;band<3;band++){GL11.glColor4f((rgb>>16&255)/255f,(rgb>>8&255)/255f,(rgb&255)/255f,.65f/(band+1));GL11.glBegin(GL11.GL_LINE_STRIP);for(int i=0;i<=72;i++){double a=time*2+i*Math.PI/36,rr=r+band*.04;GL11.glVertex3d(x+Math.cos(a)*rr,y+.06*Math.sin(a*3-time),z+Math.sin(a)*rr);}GL11.glEnd();}}
    private static void tag(net.minecraft.entity.player.EntityPlayer p,double x,double y,double z,float t){Minecraft m=Minecraft.getMinecraft();GL11.glPushAttrib(GL11.GL_ALL_ATTRIB_BITS);GL11.glPushMatrix();try{GL11.glTranslated(p.lastTickPosX+(p.posX-p.lastTickPosX)*t-x,p.lastTickPosY+(p.posY-p.lastTickPosY)*t-y+p.height+.35,p.lastTickPosZ+(p.posZ-p.lastTickPosZ)*t-z);GL11.glRotatef(-m.getRenderManager().playerViewY,0,1,0);GL11.glRotatef(m.getRenderManager().playerViewX,1,0,0);GL11.glScalef(-.025f,-.025f,.025f);String text=p.getName()+" / "+Math.round(p.getHealth())+" HP";int w=m.fontRendererObj.getStringWidth(text);GL11.glDisable(GL11.GL_LIGHTING);GL11.glEnable(GL11.GL_TEXTURE_2D);m.fontRendererObj.drawString(text,-w/2,0,0xffd2b6ff);tagFrames++;}finally{GL11.glPopMatrix();GL11.glPopAttrib();}}
}
